select status, start_cohort, pct_paused from (select status, case when year(start_date) < 2024 then 'before_2024' when year(start_date) = 2024 then '2024' else 'after_2024' end as start_cohort, round((100 * sum(case when status = 'PAUSED' then 1 else 0 end)) / count(*), 1) as pct_paused from subscriptions group by status, case when year(start_date) < 2024 then 'before_2024' when year(start_date) = 2024 then '2024' else 'after_2024' end) as s where pct_paused > 58 order by status desc
